package ru.aibuyer.mvp.catalog;

import com.fasterxml.jackson.databind.JsonNode;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import ru.aibuyer.mvp.auth.ApiException;

@Service
public class CatalogService {
 private final JdbcTemplate db;
 public CatalogService(JdbcTemplate db){this.db=db;}
 static ApiException error(int status,String code){return new ApiException(status,code,code);}
 public static long id(String s){try{if(!s.matches("[1-9][0-9]{0,18}"))throw new Exception();return Long.parseLong(s);}catch(Exception e){throw error(400,"BAD_REQUEST");}}
 static int integer(JsonNode b,String field){var n=b.get(field);if(n==null||!n.isIntegralNumber()||!n.canConvertToInt()||n.intValue()<0)throw error(422,"VALIDATION_ERROR");return n.intValue();}
 static String str(JsonNode b,String field,int max,boolean nullable){var n=b.get(field);if(nullable&&(n==null||n.isNull()))return null;if(n==null||!n.isTextual()||n.asText().trim().isEmpty()||n.asText().trim().length()>max)throw error(422,"VALIDATION_ERROR");return n.asText().trim();}
 static void fields(JsonNode b,String... allowed){if(b==null||!b.isObject())throw error(400,"BAD_REQUEST");var names=Set.of(allowed);b.fieldNames().forEachRemaining(n->{if(!names.contains(n))throw error(400,"BAD_REQUEST");});}
 static LocalDate date(String s){try{if(s==null||!s.matches("\\d{4}-\\d{2}-\\d{2}"))throw new Exception();var d=LocalDate.parse(s);if(d.isAfter(LocalDate.now(ZoneOffset.UTC)))throw new Exception();return d;}catch(Exception e){throw error(400,"BAD_REQUEST");}}
 private void lock(long company){db.queryForObject("SELECT id FROM company WHERE id=? FOR UPDATE",Long.class,company);}
 private void revision(long company){if(db.update("UPDATE company SET data_revision=data_revision+1 WHERE id=? AND data_revision<2147483647",company)!=1)throw error(422,"NUMERIC_OVERFLOW");}
 private static void version(Map<String,Object> current,int version){if(((Number)current.get("version")).intValue()!=version)throw error(409,"VERSION_CONFLICT");}
 private static int next(int version){if(version==Integer.MAX_VALUE)throw error(422,"NUMERIC_OVERFLOW");return version+1;}
 private long insert(String sql,Object... args){var keys=new GeneratedKeyHolder();db.update(c->{var p=c.prepareStatement(sql,new String[]{"id"});for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);return p;},keys);return Objects.requireNonNull(keys.getKey()).longValue();}
 private Map<String,Object> convert(Map<String,Object> row){var out=new LinkedHashMap<String,Object>();row.forEach((k,v)->{String[] parts=k.toLowerCase(Locale.ROOT).split("_");String key=parts[0];for(int i=1;i<parts.length;i++)key+=Character.toUpperCase(parts[i].charAt(0))+parts[i].substring(1);if(v!=null&&(key.equals("id")||key.endsWith("Id")))v=v.toString();if(v instanceof OffsetDateTime t)v=t.toInstant().toString();if(v instanceof java.sql.Timestamp t)v=t.toInstant().toString();if(v instanceof java.sql.Date d)v=d.toString();out.put(key,v);});return out;}
 private List<Map<String,Object>> rows(String sql,Object... args){return db.queryForList(sql,args).stream().map(this::convert).toList();}
 public Map<String,Object> product(long c,long id){var rows=rows("SELECT * FROM product WHERE company_id=? AND id=?",c,id);if(rows.isEmpty())throw error(404,"RESOURCE_NOT_FOUND");return rows.get(0);}
 public Map<String,Object> inventory(long c,long id){product(c,id);return rows("SELECT product_id,quantity,version,updated_at FROM inventory WHERE company_id=? AND product_id=?",c,id).get(0);}
 @Transactional public Map<String,Object> create(long c,JsonNode b){fields(b,"sku","name","category","preferredSupplierId");String sku=str(b,"sku",100,false),name=str(b,"name",255,false),category=str(b,"category",255,true);if(b.hasNonNull("preferredSupplierId"))throw error(422,"VALIDATION_ERROR");lock(c);long id;try{id=insert("INSERT INTO product(company_id,sku,name,category) VALUES (?,?,?,?)",c,sku,name,category);}catch(org.springframework.dao.DuplicateKeyException e){throw error(409,"SKU_ALREADY_EXISTS");}db.update("INSERT INTO inventory(company_id,product_id) VALUES (?,?)",c,id);revision(c);return product(c,id);}
 @Transactional public Map<String,Object> patch(long c,long id,JsonNode b){fields(b,"sku","name","category","preferredSupplierId","version");if(b.size()<2)throw error(422,"VALIDATION_ERROR");lock(c);var p=product(c,id);int v=integer(b,"version");version(p,v);String sku=b.has("sku")?str(b,"sku",100,false):(String)p.get("sku"),name=b.has("name")?str(b,"name",255,false):(String)p.get("name"),category=b.has("category")?str(b,"category",255,true):(String)p.get("category");if(b.hasNonNull("preferredSupplierId")){id(str(b,"preferredSupplierId",19,false));throw error(404,"RESOURCE_NOT_FOUND");}if(Objects.equals(sku,p.get("sku"))&&Objects.equals(name,p.get("name"))&&Objects.equals(category,p.get("category")))return p;try{db.update("UPDATE product SET sku=?,name=?,category=?,version=?,updated_at=CURRENT_TIMESTAMP WHERE company_id=? AND id=?",sku,name,category,next(v),c,id);}catch(org.springframework.dao.DuplicateKeyException e){throw error(409,"SKU_ALREADY_EXISTS");}revision(c);return product(c,id);}
 @Transactional public void delete(long c,long id,int v){lock(c);var p=product(c,id);version(p,v);if(((Number)inventory(c,id).get("quantity")).intValue()!=0||db.queryForObject("SELECT COUNT(*) FROM sale WHERE company_id=? AND product_id=?",Long.class,c,id)>0)throw error(409,"RESOURCE_IN_USE");db.update("DELETE FROM inventory WHERE company_id=? AND product_id=?",c,id);db.update("DELETE FROM product WHERE company_id=? AND id=?",c,id);revision(c);}
 @Transactional public Map<String,Object> setInventory(long c,long id,JsonNode b){fields(b,"quantity","version");lock(c);var p=inventory(c,id);int q=integer(b,"quantity"),v=integer(b,"version");version(p,v);if(((Number)p.get("quantity")).intValue()==q)return p;db.update("UPDATE inventory SET quantity=?,version=?,updated_at=CURRENT_TIMESTAMP WHERE company_id=? AND product_id=?",q,next(v),c,id);revision(c);return inventory(c,id);}
 @Transactional public Map<String,Object> setSale(long c,long id,String day,JsonNode b){fields(b,"quantity","version");var date=date(day);lock(c);product(c,id);int q=integer(b,"quantity"),v=integer(b,"version");var result=rows("SELECT id,created_at,product_id,sale_date,quantity,version FROM sale WHERE company_id=? AND product_id=? AND sale_date=?",c,id,date);if(result.isEmpty()){if(v!=0)throw error(409,"VERSION_CONFLICT");insert("INSERT INTO sale(company_id,product_id,sale_date,quantity) VALUES (?,?,?,?)",c,id,date,q);}else{var p=result.get(0);version(p,v);if(((Number)p.get("quantity")).intValue()==q)return p;db.update("UPDATE sale SET quantity=?,version=? WHERE company_id=? AND product_id=? AND sale_date=?",q,next(v),c,id,date);}revision(c);return rows("SELECT id,created_at,product_id,sale_date,quantity,version FROM sale WHERE company_id=? AND product_id=? AND sale_date=?",c,id,date).get(0);}
 public static int number(String s,int fallback){if(s==null)return fallback;try{if(!s.matches("[0-9]+"))throw new Exception();return Integer.parseInt(s);}catch(Exception e){throw error(400,"BAD_REQUEST");}}
 private Map<String,Object> page(String select,String where,String order,List<Object> args,Map<String,String> query){int page=number(query.get("page"),0),size=number(query.get("size"),20);if(size<1||size>100)throw error(400,"BAD_REQUEST");long total=db.queryForObject("SELECT COUNT(*) "+where,Long.class,args.toArray());if(total>Integer.MAX_VALUE)throw error(422,"NUMERIC_OVERFLOW");var params=new ArrayList<>(args);params.add(size);params.add((long)page*size);return Map.of("items",rows(select+" "+where+" ORDER BY "+order+" LIMIT ? OFFSET ?",params.toArray()),"page",page,"size",size,"totalElements",total,"totalPages",(total+size-1)/size);}
 public Map<String,Object> products(long c,Map<String,String> q){String where="FROM product WHERE company_id=?";var args=new ArrayList<Object>(List.of(c));if(q.containsKey("q")){String term=q.get("q").trim();if(term.isEmpty())throw error(400,"BAD_REQUEST");where+=" AND (POSITION(LOWER(?) IN LOWER(sku))>0 OR POSITION(LOWER(?) IN LOWER(name))>0)";args.add(term);args.add(term);}if(q.containsKey("category")){String category=q.get("category").trim();if(category.isEmpty())throw error(400,"BAD_REQUEST");where+=" AND category=?";args.add(category);}String order=switch(q.getOrDefault("sort","name,asc")){case "name,asc"->"name ASC,id ASC";case "name,desc"->"name DESC,id ASC";case "sku,asc"->"sku ASC,id ASC";case "createdAt,desc"->"created_at DESC,id ASC";default->throw error(400,"BAD_REQUEST");};return page("SELECT *",where,order,args,q);}
 public Map<String,Object> inventories(long c,Map<String,String> q){String where="FROM inventory WHERE company_id=?";var args=new ArrayList<Object>(List.of(c));if(q.containsKey("productId")){long id=id(q.get("productId"));product(c,id);where+=" AND product_id=?";args.add(id);}return page("SELECT product_id,quantity,version,updated_at",where,"product_id ASC",args,q);}
 public Map<String,Object> sales(long c,Map<String,String> q,boolean summary){var from=date(q.get("dateFrom"));var to=date(q.get("dateTo"));if(from.isAfter(to)||java.time.temporal.ChronoUnit.DAYS.between(from,to)>365)throw error(400,"BAD_REQUEST");String where="FROM sale WHERE company_id=? AND sale_date>=? AND sale_date<=?";var args=new ArrayList<Object>(List.of(c,from,to));if(q.containsKey("productId")){long id=id(q.get("productId"));product(c,id);where+=" AND product_id=?";args.add(id);}if(!summary)return page("SELECT id,created_at,product_id,sale_date,quantity,version",where,"sale_date DESC,id ASC",args,q);long total=db.queryForObject("SELECT COALESCE(SUM(CAST(quantity AS BIGINT)),0) "+where,Long.class,args.toArray());long count=db.queryForObject("SELECT COUNT(DISTINCT CASE WHEN quantity>0 THEN product_id END) "+where,Long.class,args.toArray());if(total>9007199254740991L||count>Integer.MAX_VALUE)throw error(422,"NUMERIC_OVERFLOW");return Map.of("dateFrom",from.toString(),"dateTo",to.toString(),"totalQuantity",total,"productCount",count);}
}
